cat > tests/test_greet.py <<'EOF'
"""Tests for greeting a person by name."""

import pytest

from greeter.greet import greet


@pytest.mark.req("greeting/a-name-is-greeted")
def test_a_name_is_greeted():
    assert greet("Ada") == "Hello, Ada!"


@pytest.mark.req("greeting/a-blank-name-is-refused")
def test_a_blank_name_is_refused():
    with pytest.raises(ValueError):
        greet("  ")
EOF
unset VIRTUAL_ENV; uv run pytest tests/test_greet.py -q 2>&1 | tail -5; echo EXIT ${PIPESTATUS[0]}
